export function fmtHhi(n: number): string {
  return n.toLocaleString("en-US");
}

export function fmtT(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k T`;
  return `${n.toFixed(0)} T`;
}

