                  <Tooltip cursor={{ strokeDasharray: "3 3" }} />
                  <Scatter data={TOKEN_VS_OWNERSHIP} name="Brand">
                    {TOKEN_VS_OWNERSHIP.map((r) => (
                      <Cell key={r.id} fill={r.color} />
